import{z as B,x as A,o as i,c as T,q as o,j as l,D as E,d as t,s as n,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"MTF","description":"","frontmatter":{"title":"MTF","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mtf-optics.md","filePath":"litho/mtf-optics.md","lastUpdated":1791413859000}'),m={name:"litho/mtf-optics.md"};function F(p,a,d,h,M,C){const r=A("Mermaid");return i(),T("div",null,[a[2]||(a[2]=o('<h1 id="mtf" tabindex="-1">MTF <a class="header-anchor" href="#mtf" aria-label="Permalink to &quot;MTF&quot;">​</a></h1><div class="epigraph"><p>NILS 问一条边在阈值处有多陡；调制传递函数问：正弦物的调制度随空间频率怎样被光学系统吃掉。</p><footer>—— Goodman, Introduction to Fourier Optics 的 OTF / MTF；光刻读法见 Mack</footer></div><p><a href="/litho/nils-ils">上一课</a>把工艺灵敏度钉在阈值处的 \\(\\mathrm{ILS}/\\mathrm{NILS}\\)。缺口是：<strong>还没有一条「频率 → 还剩多少调制」的传递曲线</strong>。NILS 依赖具体图形与阈值；MTF 先对正弦物说话。离焦如何沿轴毁掉调制，留给<a href="/litho/depth-of-focus">焦深</a>。不要把 MTF 写成产线 \\(k_1\\)，也不要引用未公开的镜头验收 MTF 表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对比度 \\(C\\) 对密栅是一个数，对「所有节距」不是一条函数。线性（非相干）系统里，物调制度乘光学传递函数（OTF）得到像调制度；MTF 是其模。光刻照明是部分相干，严格传递是 Hopkins 的双线性核，不是单条 MTF——但单条 MTF 仍是读「高频先死」的最短语言。缺口因此是这条频率轴上的传递，而不是再乘一次目标 CD。</p><p><span class="marginnote">术语翻译：MTF（调制传递函数）回答「不同粗细的条纹经过镜头后，亮暗对比还剩几成」：1 是原样保留，0 是糊成一片灰。粗条纹（低频）通常保留得好，细条纹（高频）先被吃掉——这就是「高频先死」。</span></p><p>上一课已经说明 \\(C\\) 与 NILS 不可互换。本课补的差是：正弦传递与阈值斜率也不可互换。同一套空中像，可以 MTF 看起来还行，切在缓坡上则 NILS 已经死。</p><h3 id="相干、非相干、部分相干三条截止" tabindex="-1">相干、非相干、部分相干三条截止 <a class="header-anchor" href="#相干、非相干、部分相干三条截止" aria-label="Permalink to &quot;相干、非相干、部分相干三条截止&quot;">​</a></h3><p>完全相干：复振幅的传递就是光瞳，截止 \\(\\mathrm{NA}/\\lambda\\)，MTF 作为强度传递不是线性的。完全非相干：MTF 是光瞳的自相关，截止 \\(2\\mathrm{NA}/\\lambda\\)，在截止处降到零。部分相干落在中间，有效截止与 \\(\\sigma\\) 有关：\\(\\sigma\\) 越大，越接近非相干的那条自相关。Mack 用这组图衔接空中像；定量工艺仍回到 NILS 与 TCC。</p><p><span class="marginnote">数字实例：EUV 的 NA=0.33、λ=13.5 nm，非相干截止 2NA/λ ≈ 49 微米⁻¹，对应能传递的最细条纹节距约 20 纳米；比这更细的条纹 MTF 直接为零，无论怎么曝光都不会出现亮暗对比。</span></p><p><span class="marginnote">显微镜习惯把 MTF 画到对比刚可分辨；光刻要的是阈值处还能切规格。把「MTF=0.3」直接叫成可印，等于又发明了一个没有胶的 \\(k_1\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>非相干点扩散的傅里叶变换（归一到零频为 1）即 OTF；MTF \\(=|\\mathrm{OTF}|\\)。圆孔无像差时，MTF 随频率近似线性下降到 \\(2\\mathrm{NA}/\\lambda\\)。离焦给 OTF 乘相位因子，MTF 出现零点与对比反转——后课焦深把零点沿 \\(z\\) 移动。像差同样压 MTF，尤其靠近截止的密图形。</p><p>光刻实践：用线栅对比度对节距扫一条「有效 MTF」，照明一换曲线就换。它是诊断图，不是 Hopkins 的替代。报曲线必须声明 \\(\\sigma\\)、偏振与是否矢量。</p><h3 id="与-nils-的分工" tabindex="-1">与 NILS 的分工 <a class="header-anchor" href="#与-nils-的分工" aria-label="Permalink to &quot;与 NILS 的分工&quot;">​</a></h3><p>正弦物的 MTF 在某个频率高，只说明该频率的亮暗差还在；边沿位置由所有频率叠加后的局部斜率决定。孤立线的频谱很宽，NILS 吃的是整条加权，不是单点 MTF。设计规则里用 NILS 设门槛，用 MTF 解释「为什么密节距先糊」。</p><p><span class="marginnote">OTF 可以是负的（对比反转），MTF 取绝对值会丢掉符号。光刻里反转意味着空中像的峰谷对调，阈值模型会切出完全错误的线宽。</span></p>',17)),(i(),l(s,null,{default:E(()=>[n(r,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20NILS%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%E9%98%88%E5%80%BC%E6%96%9C%E7%8E%87%22%5D%20--%3E%20GAP%5B%22%E6%9C%AC%E8%AF%BE%EF%BC%9A%E9%A2%91%E7%8E%87%E4%BC%A0%E9%80%92%22%5D%0A%20%20SIN%5B%22%E6%AD%A3%E5%BC%A6%E7%89%A9%E8%B0%83%E5%88%B6%22%5D%20--%3E%20MTF%5B%22MTF%20%2F%20OTF%22%5D%0A%20%20PUP%5B%22%E5%85%89%E7%9E%B3%22%5D%20--%3E%20MTF%0A%20%20SIG%5B%22%CF%83%20%2F%20%E9%83%A8%E5%88%86%E7%9B%B8%E5%B9%B2%22%5D%20--%3E%20MTF%0A%20%20MTF%20--%3E%20DOF%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%A6%BB%E7%84%A6%E6%89%93%E9%9B%B6%E7%82%B9%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[t("非相干成像是强度卷积，频率域相乘，高频对应光瞳里相距很远的两点的相关，自相关面积变小，MTF 下降。相干成像是场卷积，强度再取模方，不存在单条 MTF。部分相干把许多互不相干的源点各自做相干成像再加强度，有效传递介于两者之间——这与"),e("a",{href:"/litho/partial-coherence"},"部分相干"),t("课的 \\(\\sigma\\) 是同一机制的频率语言。")],-1)),a[5]||(a[5]=e("p",null,"切趾改光瞳自相关，因而改非相干 MTF；像差主要改相位，MTF 掉、还可能出旁瓣。本课不展开 Zernike；只承认 \\(P\\) 的相位已经能进 OTF。",-1)),(i(),l(s,null,{default:E(()=>[n(r,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20ILL%5B%22%E7%85%A7%E6%98%8E%E7%9B%B8%E5%B9%B2%E5%BA%A6%22%5D%20--%3E%20COH%5B%22%E5%AE%8C%E5%85%A8%E7%9B%B8%E5%B9%B2%22%5D%0A%20%20ILL%20--%3E%20PART%5B%22%E9%83%A8%E5%88%86%E7%9B%B8%E5%B9%B2%20%CF%83%20%E5%B1%85%E4%B8%AD%22%5D%0A%20%20ILL%20--%3E%20INC%5B%22%E5%AE%8C%E5%85%A8%E9%9D%9E%E7%9B%B8%E5%B9%B2%22%5D%0A%20%20COH%20--%3E%20C1%5B%22%E6%88%AA%E6%AD%A2%20NA%2F%CE%BB%20%E5%BC%BA%E5%BA%A6%E4%BC%A0%E9%80%92%E9%9D%9E%E7%BA%BF%E6%80%A7%22%5D%0A%20%20INC%20--%3E%20C2%5B%22MTF%3D%E5%85%89%E7%9E%B3%E8%87%AA%E7%9B%B8%E5%85%B3%20%E6%88%AA%E6%AD%A2%202NA%2F%CE%BB%22%5D%0A%20%20PART%20--%3E%20C3%5B%22%E6%9C%89%E6%95%88%E4%BC%A0%E9%80%92%E5%9C%A8%E4%B8%A4%E8%80%85%E4%B9%8B%E9%97%B4%22%5D%0A%20%20C2%20--%3E%20HI%5B%22%E6%9C%80%E9%AB%98%E9%A2%91%E7%8E%87%E5%AE%B9%E9%87%8F%22%5D%0A%20%20C3%20--%3E%20HI%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">直觉类比：非相干 MTF 是光瞳的「自重叠率」——想象把光瞳纸片贴着自己平移，重叠面积占比就是该频率的 MTF。平移越远（频率越高）重叠越少，直到完全不重叠（截止）；离焦相当于把纸片揉出褶皱，重叠掉得更快，还会出现反相的零点。</span></p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到「光学还剩多少调制」，正弦语言用 MTF，边与窗口用 NILS，完整计算用 TCC。下一课把离焦写成二次相位，MTF\\((f;z)\\) 与 NILS\\((z)\\) 一起掉。不要在焦深公式里用 MTF 零点冒充 \\(k_2\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>MTF 不含胶扩散、不含 SEM 偏置。矢量成像改的是进入 OTF 的那张 \\(I\\)，定义不变。禁止把某代投影物镜的「衍射极限 MTF」写成未公开验收数；Goodman 的圆孔曲线与 Mack 的光刻读法已经够用。二维图形没有单条 MTF 能概括拐角。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MTF 是正弦物调制度随频率的传递；NILS 是阈值处的边斜率。</li><li>非相干截止 \\(2\\mathrm{NA}/\\lambda\\)，相干截止 \\(\\mathrm{NA}/\\lambda\\)，部分相干居中。</li><li>离焦与像差压 MTF，并可造成对比反转。</li><li>光刻定量仍以 NILS / TCC 为准，MTF 是读高频先死的短语言。</li><li>轴向窗口下一课。</li><li>出处：Goodman, <em>Introduction to Fourier Optics</em>；Mack, <em>Fundamental Principles of Optical Lithography</em>。</li></ul>',7))])}const u=B(m,[["render",F]]);export{f as __pageData,u as default};
